cd /workspace/task && python3 - <<'EOF'
import openpyxl
wb = openpyxl.load_workbook('init.xlsx', data_only=False)
comp = wb['Compiled and located schools da']
ul = wb['URN lookup']

ul_rows = []
for r in range(2, ul.max_row+1):
    ul_rows.append((ul.cell(r,1).value, ul.cell(r,4).value, ul.cell(r,6).value))  # URN, ESTAB, SCHNAME

# name->estab from lookup
name2estab={}
for urn,estab,name in ul_rows:
    if name:
        name2estab.setdefault(name.strip().lower(), set()).add(estab)

# Compare compiled col C with name matching
mismatch=0
filled=0
for r in range(2, comp.max_row+1):
    c=comp.cell(r,3).value
    name=comp.cell(r,5).value
    if name:
        key=name.strip().lower()
        if key in name2estab:
            est = list(name2estab[key])
            if c is not None:
                filled+=1
                if c not in est:
                    mismatch+=1
                    if mismatch<20:
                        print("MISMATCH row",r,"name",name,"C",c,"lookup estab",est)
print("filled C rows:",filled,"mismatches:",mismatch)
EOF
